@@ -1,10 +1,12 @@
 package hotel.reservations;

+import hotel.reservations.seasons.Season;
+import hotel.reservations.seasons.SeasonCalendar;
 import hotel.rooms.Room;
 import java.math.BigDecimal;
 import java.math.RoundingMode;
 import java.time.LocalDate;
-import java.time.Month;
+import java.util.Optional;

 /**
  * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
@@ -13,7 +15,7 @@ import java.time.Month;
  */
 public final class PriceCalculator {

-    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
+    private static final SeasonCalendar SEASONS = new SeasonCalendar();
     static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");

     public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
@@ -32,19 +34,15 @@ public final class PriceCalculator {

     BigDecimal nightPrice(Room room, LocalDate night) {
         BigDecimal nightlyRate = room.nightlyRate();
-        if (isHighSeason(night)) {
-            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
+        Optional<Season> season = SEASONS.seasonOf(night);
+        if (season.isPresent()) {
+            return cents(nightlyRate.multiply(BigDecimal.ONE.add(season.get().surcharge())));
         }
         return cents(nightlyRate);
     }

-    /** High season: from December 15 to the end of February, and the whole of July. */
     static boolean isHighSeason(LocalDate date) {
-        Month month = date.getMonth();
-        return month == Month.JANUARY
-                || month == Month.FEBRUARY
-                || month == Month.JULY
-                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
+        return SEASONS.seasonOf(date).isPresent();
     }

     static BigDecimal cents(BigDecimal value) {
diff --git a/src/main/java/hotel/reservations/seasons/EasterWeek.java b/src/main/java/hotel/reservations/seasons/EasterWeek.java
new file mode 100644
index 0000000..224aa83
--- /dev/null
+++ b/src/main/java/hotel/reservations/seasons/EasterWeek.java
@@ -0,0 +1,26 @@
+package hotel.reservations.seasons;
+
+import java.math.BigDecimal;
+import java.time.LocalDate;
+
+/** From Palm Sunday to Easter Sunday, both nights included. */
+public final class EasterWeek implements Season {
+
+    private final LocalDate palmSunday;
+    private final LocalDate easterSunday;
+
+    public EasterWeek(LocalDate palmSunday, LocalDate easterSunday) {
+        this.palmSunday = palmSunday;
+        this.easterSunday = easterSunday;
+    }
+
+    @Override
+    public boolean includes(LocalDate night) {
+        return !night.isBefore(palmSunday) && !night.isAfter(easterSunday);
+    }
+
+    @Override
+    public BigDecimal surcharge() {
+        return new BigDecimal("0.25");
+    }
+}
diff --git a/src/main/java/hotel/reservations/seasons/JulyHolidays.java b/src/main/java/hotel/reservations/seasons/JulyHolidays.java
new file mode 100644
index 0000000..0e7b1e5
--- /dev/null
+++ b/src/main/java/hotel/reservations/seasons/JulyHolidays.java
@@ -0,0 +1,19 @@
+package hotel.reservations.seasons;
+
+import java.math.BigDecimal;
+import java.time.LocalDate;
+import java.time.Month;
+
+/** The whole of July. */
+public final class JulyHolidays implements Season {
+
+    @Override
+    public boolean includes(LocalDate night) {
+        return night.getMonth() == Month.JULY;
+    }
+
+    @Override
+    public BigDecimal surcharge() {
+        return new BigDecimal("0.25");
+    }
+}
