    68	    @Test
    69	    void nonRefundableTakes15PercentOffRoundingHalfEven() {
    70	        Price price = calculator.calculate(
    71	                standardRoom, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 11), RatePlan.NON_REFUNDABLE);
    72	
    73	        // 15% of 249.90 = 37.485, which rounds half-even to 37.48 (half-up would give 37.49)
    74	        assertEquals(new BigDecimal("37.48"), price.discount());
    75	        assertEquals(new BigDecimal("212.42"), price.total());
    76	    }
    77	
    78	    @Test
    79	    void nonRefundableDiscountIsOnTheHighSeasonPrice() {
    80	        Price price = calculator.calculate(
    81	                suite, LocalDate.of(2027, 1, 5), LocalDate.of(2027, 1, 9), RatePlan.NON_REFUNDABLE);
    82	
